def run_head2head(args):
    print("[Head2Head] Starting experiment with dataset=", args.dataset)
    results = []
    ds = make_dataset(args.dataset, args.data_root, args.image_size)
    for model_type in ['unet', 'r2']:
        for seed in args.seeds:
            print(f"[Head2Head] Model={model_type}, seed={seed}")
            set_seed(seed)
            cfg = ModelConfig(model_type=model_type, image_size=args.image_size, base_channels=args.base_channels, lora_rank=args.lora_rank, K=args.K)
            model = make_model(cfg)
            if args.grad_quant and model_type == 'r2':
                model = DummyGradQuantWrapper(model, enabled=True)
            accelerator = Accelerator(mixed_precision=args.mixed_precision)
            dl = DataLoader(ds, batch_size=args.batch_size, shuffle=True, num_workers=args.num_workers, drop_last=True)
            scheduler = DDPMScheduler(num_train_timesteps=1000)
            optimizer = torch.optim.AdamW(model.parameters(), lr=args.lr, betas=(0.9, 0.999), weight_decay=0.0)
            model, optimizer, dl = accelerator.prepare(model, optimizer, dl)
            ema = EMA(model, args.ema_decay) if args.use_ema else None

            reset_peak_memory()
            train_stats = train_one_epoch(accelerator, model, scheduler, optimizer, ema, dl)
            train_peak = peak_memory_gb()
            print(f"[Head2Head] Model={model_type} seed={seed} loss={train_stats['loss']:.4f} ips={train_stats['ips']:.1f} train_peak_gb={train_peak:.2f}")

            # Short inference VRAM check (last 50 steps)
            model_eval = model
            if ema is not None:
                ema.copy_to(model_eval)
            scheduler.set_timesteps(1000)
            def infer_short():
                b = args.eval_batch
                x = torch.randn(b, 3, args.image_size, args.image_size, device=accelerator.device)
                for t in scheduler.timesteps[-50:]:
                    tb = torch.full((b,), int(t), device=accelerator.device, dtype=torch.long)
                    pred = model_eval(x, tb).sample
                    x = scheduler.step(pred, int(t), x).prev_sample
                return x
            _, infer_peak, infer_time = measure_peak_vram(infer_short)
            print(f"[Head2Head] Inference (50-step tail) peak_gb={infer_peak:.2f} time_s={infer_time:.2f}")

            # Full sampling metrics (optionally reduced for speed)
            n_samples = min(args.num_samples, 5000 if args.dataset == 'synthetic' else args.num_samples)
            samples = sample_images(model_eval, scheduler, n_samples, args.image_size, accelerator.device, batch=args.eval_batch)
            metrics = compute_metrics_from_samples(samples, args.dataset, args.data_root, tmp_dir=os.path.join(args.out, 'tmp_head2head'))

            row = dict(exp='head2head', dataset=args.dataset, img_size=args.image_size, model=model_type, seed=seed,
                       loss=train_stats['loss'], ips=train_stats['ips'], train_peak_gb=train_peak,
                       infer_peak_gb=infer_peak, infer_time_s=infer_time,
                       fid=metrics.get('frechet_inception_distance', float('nan')))
            results.append(row)
            df = pd.DataFrame(results)
            os.makedirs(args.out, exist_ok=True)
            df.to_csv(os.path.join(args.out, 'head2head.csv'), index=False)

    df = pd.DataFrame(results)
    plot_head2head(df, args.out)
    print("[Head2Head] Completed. Results saved to:", args.out)


def run_ablation(args):
