    for seed in args.seeds:
        set_seed(seed)
        for reversible in [True, False]:
            for recurrent in [True, False]:
                for lora_rank in [0, 2, 4, 8]:
                    for grad_quant in [False, True]:
                        print(f"[Ablation] seed={seed} rev={reversible} rec={recurrent} r={lora_rank} q={grad_quant}")
                        cfg = ModelConfig(model_type='r2', image_size=args.image_size, base_channels=args.base_channels,
                                          lora_rank=lora_rank, reversible=reversible, recurrent=recurrent, K=args.K)
                        model = make_model(cfg)
                        if grad_quant:
                            model = DummyGradQuantWrapper(model, enabled=True)
                        accelerator = Accelerator(mixed_precision=args.mixed_precision)
                        dl = DataLoader(ds, batch_size=args.batch_size, shuffle=True, num_workers=args.num_workers, drop_last=True)
                        scheduler = DDPMScheduler(num_train_timesteps=1000)
                        optimizer = torch.optim.AdamW(model.parameters(), lr=args.lr)
                        model, optimizer, dl = accelerator.prepare(model, optimizer, dl)
                        ema = EMA(model, args.ema_decay) if args.use_ema else None

                        reset_peak_memory()
                        stats = train_one_epoch(accelerator, model, scheduler, optimizer, ema, dl)
                        train_peak = peak_memory_gb()
                        n_samples = min(args.num_samples, 10000)
                        if ema is not None:
                            ema.copy_to(model)
                        samples = sample_images(model, scheduler, n_samples, args.image_size, accelerator.device, batch=args.eval_batch, steps=200)
                        metrics = compute_metrics_from_samples(samples, args.dataset, args.data_root, tmp_dir=os.path.join(args.out, 'tmp_ablation'))

                        row = dict(exp='ablation', dataset=args.dataset, img_size=args.image_size, seed=seed,
                                   reversible=reversible, recurrent=recurrent, lora_rank=lora_rank, grad_quant=grad_quant,
                                   loss=stats['loss'], ips=stats['ips'], train_peak_gb=train_peak,
                                   fid=metrics.get('frechet_inception_distance', float('nan')))
                        results.append(row)
                        df = pd.DataFrame(results)
                        os.makedirs(args.out, exist_ok=True)
                        df.to_csv(os.path.join(args.out, 'ablation.csv'), index=False)
    df = pd.DataFrame(results)
    plot_ablation(df, args.out)
    print("[Ablation] Completed. Results saved to:", args.out)


def run_hires(args):
    print("[HiRes] Starting high-resolution test on dataset=", args.dataset)
    results = []
    ds = make_dataset(args.dataset, args.data_root, args.image_size)
    for model_type in ['unet', 'r2']:
        for seed in args.seeds:
            print(f"[HiRes] Model={model_type} seed={seed}")
            set_seed(seed)
            cfg = ModelConfig(model_type=model_type, image_size=args.image_size, base_channels=args.base_channels, lora_rank=args.lora_rank, K=args.K)
            model = make_model(cfg)
            accelerator = Accelerator(mixed_precision=args.mixed_precision)
            dl = DataLoader(ds, batch_size=args.batch_size, shuffle=True, num_workers=args.num_workers, drop_last=True)
            scheduler = DDPMScheduler(num_train_timesteps=1000)
            optimizer = torch.optim.AdamW(model.parameters(), lr=args.lr)
            model, optimizer, dl = accelerator.prepare(model, optimizer, dl)

            reset_peak_memory()
            stats = train_one_epoch(accelerator, model, scheduler, optimizer, None, dl)
            train_peak = peak_memory_gb()
            print(f"[HiRes] Train loss={stats['loss']:.4f} ips={stats['ips']:.1f} peak_gb={train_peak:.2f}")

            scheduler.set_timesteps(1000)
            for res in [256, 512] + ([1024] if args.test_1024 else []):
                def infer_once():
                    b = min(args.eval_batch, 2)
                    x = torch.randn(b, 3, res, res, device=accelerator.device)
                    for t in scheduler.timesteps[-50:]:
                        tb = torch.full((b,), int(t), device=accelerator.device, dtype=torch.long)
                        pred = model(x, tb).sample
                        x = scheduler.step(pred, int(t), x).prev_sample
                    return x
                _, infer_peak, infer_time = measure_peak_vram(infer_once)
                row = dict(exp='hires', dataset=args.dataset, model=model_type, seed=seed, resolution=res,
                           train_peak_gb=train_peak, infer_peak_gb=infer_peak, infer_time_s=infer_time)
                results.append(row)
                df = pd.DataFrame(results)
                os.makedirs(args.out, exist_ok=True)
                df.to_csv(os.path.join(args.out, 'hires.csv'), index=False)
                print(f"[HiRes] res={res} infer_peak_gb={infer_peak:.2f} time_s={infer_time:.2f}")

    # Simple plots for hires inference memory
    df = pd.DataFrame(results)
    if not df.empty:
        fig, ax = plt.subplots(figsize=(6, 4))
        sns.lineplot(data=df, x='resolution', y='infer_peak_gb', hue='model', marker='o', ax=ax)
        ax.set_title('Inference peak VRAM vs resolution')
        ax.set_xlabel('Resolution'); ax.set_ylabel('Peak GB')
        save_plot(fig, os.path.join(args.out, 'inference_memory_hires.pdf'))
    print("[HiRes] Completed. Results saved to:", args.out)


# ===============
# Quick functionality test (fast)
# ===============

def run_quick_test(args):
    print("[QuickTest] Verifying pipeline on synthetic patterns (fast)")
    args.dataset = 'synthetic'
    args.image_size = 32
    args.batch_size = 16
    args.eval_batch = 8
    args.num_samples = 128
    args.seeds = [0]
    args.mixed_precision = 'no'  # avoid AMP setup overhead on CPU
    os.makedirs(args.out, exist_ok=True)

    # Train UNet and R2 briefly
    rows = []
    for model_type in ['unet', 'r2']:
        set_seed(0)
        cfg = ModelConfig(model_type=model_type, image_size=args.image_size, base_channels=32, lora_rank=2, K=2)
        model = make_model(cfg)
        accelerator = Accelerator(mixed_precision=args.mixed_precision)
        ds = make_dataset(args.dataset, None, args.image_size)
        dl = DataLoader(ds, batch_size=args.batch_size, shuffle=True, num_workers=0, drop_last=True)
        scheduler = DDPMScheduler(num_train_timesteps=50)  # small for test
        optimizer = torch.optim.AdamW(model.parameters(), lr=1e-3)
        model, optimizer, dl = accelerator.prepare(model, optimizer, dl)
        ema = EMA(model, 0.999)

        reset_peak_memory()
        stats = train_one_epoch(accelerator, model, scheduler, optimizer, ema, dl)
        train_peak = peak_memory_gb()
        print(f"[QuickTest] {model_type}: loss={stats['loss']:.4f} ips={stats['ips']:.1f} peak_gb={train_peak:.2f}")

        ema.copy_to(model)
        samples = sample_images(model, scheduler, n=args.num_samples, image_size=args.image_size, device=accelerator.device, batch=args.eval_batch, steps=20)
        # Lightweight diagnostic: mean/std of samples
        m = samples.mean().item(); s = samples.std().item()
        row = dict(model=model_type, loss=stats['loss'], ips=stats['ips'], train_peak_gb=train_peak, sample_mean=m, sample_std=s)
        rows.append(row)

    df = pd.DataFrame(rows)
    df.to_csv(os.path.join(args.out, 'quick_test.csv'), index=False)

    # Plots for test
    fig, ax = plt.subplots(figsize=(6, 4))
    sns.barplot(data=df, x='model', y='loss', ax=ax)
    ax.set_title('Quick test training loss (synthetic)')
    ax.set_ylabel('loss')
    save_plot(fig, os.path.join(args.out, 'training_loss_quicktest.pdf'))

    fig, ax = plt.subplots(figsize=(6, 4))
    sns.barplot(data=df, x='model', y='train_peak_gb', ax=ax)
    ax.set_title('Quick test peak VRAM')
    ax.set_ylabel('GB')
    save_plot(fig, os.path.join(args.out, 'peak_memory_quicktest.pdf'))

    print("[QuickTest] Completed. Outputs saved to:", args.out)


# ===============
# CLI
# ===============

def parse_args():
    p = argparse.ArgumentParser()
    p.add_argument('--experiment', type=str, required=True, choices=['head2head', 'ablation', 'hires', 'quick_test'])
    p.add_argument('--dataset', type=str, default='cifar10')
    p.add_argument('--data_root', type=str, default=None)
    p.add_argument('--image_size', type=int, default=32)
    p.add_argument('--batch_size', type=int, default=64)
    p.add_argument('--eval_batch', type=int, default=64)
    p.add_argument('--num_samples', type=int, default=50000)
    p.add_argument('--lr', type=float, default=2e-4)
    p.add_argument('--base_channels', type=int, default=128)
    p.add_argument('--lora_rank', type=int, default=4)
    p.add_argument('--mixed_precision', type=str, default='fp16', choices=['no', 'fp16', 'bf16'])
    p.add_argument('--num_workers', type=int, default=4)
    p.add_argument('--use_ema', action='store_true')
    p.add_argument('--grad_quant', action='store_true')
    p.add_argument('--seeds', type=int, nargs='+', default=[0,1,2])
    p.add_argument('--K', type=int, default=3)
    p.add_argument('--out', type=str, default='out')
    p.add_argument('--test_1024', action='store_true')
    return p.parse_args()


def main():
    args = parse_args()
    os.makedirs(args.out, exist_ok=True)
    with open(os.path.join(args.out, 'args.json'), 'w') as f:
        json.dump(vars(args), f, indent=2)
    if args.experiment == 'head2head':
        run_head2head(args)
    elif args.experiment == 'ablation':
        run_ablation(args)
    elif args.experiment == 'hires':
        run_hires(args)
    else:
        run_quick_test(args)


if __name__ == '__main__':
    main()


Notes
- The R2DiffusionModel here is a dependency-light stand-in that follows the new method’s design (reversible-style coupling, recurrence, LoRA adapters) and exposes a diffusers-compatible forward (returns object with .sample). For true reversible backprop savings and axial-sparse attention, you can later swap in MemCNN/xFormers-backed implementations.
- Every experiment prints key stats to stdout and saves CSVs and PDF plots (peak_memory_*.pdf, throughput_*.pdf, training_loss_*.pdf, fid_*.pdf, inference_memory_hires.pdf). Plots are saved with bbox_inches="tight" and PDF format only, per requirement.
- The quick_test experiment completes quickly on CPU. It avoids any heavyweight downloads and uses a very small DDPM schedule. It verifies end-to-end functionality, produces metrics, and saves two PDF plots usable in regression tests.

